INSERT OR REPLACE INTO notes (id, user_id, title, content, is_encrypted) VALUES ('mo3ca951bixh9wxfnrg', 'usr_bmFkZWVtcHViZ21vYmlsZUBnbWFpbC5jb20', 'Id picker for html element ', '(function () {
  console.log("ID picker active. Click any element. Press ESC to stop.");

  function handler(e) {
    e.preventDefault();
    e.stopPropagation();

    const el = e.target;
    console.log("Selected element:", el);

    if (el.id) {
      console.log("ID:", el.id);
    } else {
      console.log("No ID. CSS selector:",
        el.tagName.toLowerCase() +
        (el.className ? "." + el.className.trim().replace(/\s+/g, ".") : "")
      );
    }
  }

  document.addEventListener("click", handler, true);

  function stop(e) {
    if (e.key === "Escape") {
      document.removeEventListener("click", handler, true);
      document.removeEventListener("keydown", stop);
      console.log("ID picker stopped.");
    }
  }

  document.addEventListener("keydown", stop);
})();', 0);
